```
public struct MD5Hash
{
    private ulong _hash1;
    private ulong _hash2;

    public MD5Hash(byte[] hashBytes)
    {
        if (hashBytes == null || hashBytes.Length != 16)
            throw new ArgumentException("Invalid MD5 hash", nameof(hashBytes));

        _hash1 = BitConverter.ToUInt64(hashBytes, 0);
        _hash2 = BitConverter.ToUInt64(hashBytes, 8);
    }

    public byte[] GetBytes()
    {
        byte[] bytes = new byte[16];

        Buffer.BlockCopy(BitConverter.GetBytes(_hash1), 0, bytes, 0, 8);
        Buffer.BlockCopy(BitConverter.GetBytes(_hash2), 0, bytes, 8, 8);

        return bytes;
    }

    public override string ToString()
    {
        return string.Concat(_hash1.ToString("X16"), _hash2.ToString("X16"));
    }
}
```

