    void HandleMovement()
    {
        float speed = _walkSpeed * (inputHandler.SprintValue > 0 ? _sprintMultiplier : 1f);

        Vector3 inputDirection = new Vector3(inputHandler.MoveInput.x, 0f, inputHandler.MoveInput.y);
        Vector3 worldDirection = transform.TransformDirection(inputDirection);
        worldDirection.Normalize();

        // Handling crouching
        if (inputHandler.CrouchTriggered)
        {
            currentMovement.x = worldDirection.x * _crouchingSpeed;
            currentMovement.z = worldDirection.z * _crouchingSpeed;
        }
        else
        {
            currentMovement.x = worldDirection.x * speed;
            currentMovement.z = worldDirection.z * speed;
        }
        characterController.Move(currentMovement * Time.deltaTime);
    }

    void HandleJumping()
    {
        if(characterController.isGrounded) 
        {
            currentMovement.y = -0.5f;

            if(inputHandler.JumpTriggered)
            {
                currentMovement.y = _jumpForce;
            }
        }
        else
        {
            currentMovement.y -= _gravity * Time.deltaTime;
        }
    }

    void HandleRotation()
    {
        float mouseXRotation = inputHandler.LookInput.x * _mouseSensitivity;
        transform.Rotate(0f, mouseXRotation, 0f);

        verticalRotation -= inputHandler.LookInput.y * _mouseSensitivity;
        verticalRotation = Mathf.Clamp(verticalRotation, -_upDownClampRange, _upDownClampRange);
        mainCamera.transform.localRotation = Quaternion.Euler(verticalRotation, 0f, 0f);
    }

    void HandleCrouching()
    {
        float characterHeight = characterController.height;

        Vector3 p1 = transform.position + Vector3.up * (characterController.radius);
        Vector3 p2 = transform.position + Vector3.up * (characterHeight - characterController.radius);

        bool isCrouch = inputHandler.CrouchTriggered;
        bool canStandUp = !Physics.CapsuleCast(p1, p2, characterController.radius, Vector3.up, _crouchingCastDistance);

