```

### Step 2: Writing the Application Logic

Open the `src/main.rs` file and replace its content with the following code:

```rust
use systray::Application;
use std::{thread, time::Duration};
use chrono::Local;

fn main() {
    // This creates a new application instance for the tray icon.
    let mut app = Application::new().expect("Unable to create tray application");

    // Add a quit item to the tray menu.
    app.add_menu_item("Quit", |window| {
        window.quit();
        Ok::<_, systray::Error>(())
    })
    .expect("Failed to add 'Quit' item");

    // Use a separate thread to handle printing timestamps
    thread::spawn(move || loop {
        // Print the current timestamp
        println!("{}", Local::now());
        // Wait for a second
        thread::sleep(Duration::new(1, 0));
    });

    // This handles the tray application event loop.
    app.wait_for_message().expect("Failed to wait for message");
}
```

