package main

import (
	"log"
	"os"
	"strconv"

	"go.uber.org/zap"
	"go.uber.org/zap/zapcore"
)

func main() {
	// Read the environment variable for logging configuration
	logToFile, _ := strconv.ParseBool(os.Getenv("LOG_TO_FILE"))

	// Configure the desired Zap logger based on the environment variable
	var logger *zap.Logger
	if logToFile {
		logger = newFileLogger()
	} else {
		logger = newConsoleLogger()
	}
	defer logger.Sync()

	// Example usage of the logger
	logger.Info("Logging initialized")
	logger.Warn("A warning message")
	logger.Error("An error message")
}

func newFileLogger() *zap.Logger {
	// Configure Zap logger to log to a file
	cfg := zap.NewProductionConfig()
	cfg.OutputPaths = []string{"logfile.txt"}

	// Create the logger
	logger, err := cfg.Build()
	if err != nil {
		log.Fatal("Failed to initialize logger: ", err)
	}

	return logger
}

func newConsoleLogger() *zap.Logger {
	// Configure Zap logger to log to the console
	cfg := zap.NewDevelopmentConfig()
	cfg.EncoderConfig.EncodeLevel = zapcore.CapitalColorLevelEncoder

	// Create the logger
	logger, err := cfg.Build()
	if err != nil {
		log.Fatal("Failed to initialize logger: ", err)
	}

	return logger
}
