            rect = (col * block_width, row * block_height, block_width, block_height)
            block = image.subsurface(rect)
            blocks.append(block)

    return blocks

# 交换方块
def swap_blocks(blocks, index1, index2):
    blocks[index1], blocks[index2] = blocks[index2], blocks[index1]

# 判断拼图是否完成
