def get_moveable_indexes(blank_index):
    moveable_indexes = []
    if blank_index % COLS > 0:
        moveable_indexes.append(blank_index - 1)
    if blank_index % COLS < COLS - 1:
        moveable_indexes.append(blank_index + 1)
    if blank_index // COLS > 0:
        moveable_indexes.append(blank_index - COLS)
    if blank_index // COLS < ROWS - 1:
        moveable_indexes.append(blank_index + COLS)
    return moveable_indexes

# 获取逆序数
def get_inversion_count(arr):
    inv_count = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] and arr[j] and arr[i] > arr[j]:
                inv_count += 1
    return inv_count

# 判断拼图是否可解
def is_puzzle_solvable(blocks):
    arr = [block if block is None else block % (ROWS * COLS) + 1 for block in blocks]
    inv_count = get_inversion_count(arr)
    blank_row = ROWS - blocks.index(None) // COLS
    if COLS % 2 == 0:
        if blank_row % 2 == 0:
            return inv_count % 2 == 1
        else:
            return inv_count % 2 == 0
    else:
        return inv_count % 2 == 0

