                mouseX = e.getX();
                mouseY = e.getY();

                // Remember the label's current position
                labelX = label.getX();
                labelY = label.getY();

                // Start dragging
                dragging = true;

                // Remember the time of the last event
                lastEventTime = e.getWhen();
            }

