        // Add a mouse motion listener to the label to handle drag events
        label.addMouseMotionListener(new MouseMotionAdapter() {
            public void mouseDragged(MouseEvent e) {
                if (dragging) {
                    // Calculate the time elapsed since the last event
                    long currentTime = e.getWhen();
                    long elapsedTime = currentTime - lastEventTime;

                    // Calculate the distance between the current mouse position and the previous mouse position
                    int dx = e.getX() - mouseX;
                    int dy = e.getY() - mouseY;

                    // Calculate the movement rate of the JLabel based on the elapsed time
                    int movementRate = (int) (Math.sqrt(dx * dx + dy * dy) / elapsedTime);

                    // Calculate the new position of the label based on the mouse movement
                    int newX = labelX + dx * movementRate;
                    int newY = labelY + dy * movementRate;

                    // Constrain the label's position to within the panel
                    newX = Math.max(0, Math.min(panel.getWidth() - label.getWidth(), newX));
                    newY = Math.max(0, Math.min(panel.getHeight() - label.getHeight(), newY));

                    // Move the label to its new position
                    label.setLocation(newX, newY);

                    // Remember the current time as the time of the last event
                    lastEventTime = currentTime;
