	SPI1->DR = ((d>>4) & 0xff);
	while((SPI1->SR & SPI_SR_BSY) == SPI_SR_BSY);
	SPI1->DR;
	SPI1->DR = ((d&0xf)<<4);
	while((SPI1->SR & SPI_SR_BSY) == SPI_SR_BSY);
	SPI1->DR;
	GPIOB->ODR |= (0x0010);
	address = address + 2;
