        public uint WriteTotalTimeoutConstant;
    }

    public static async Task<byte[]> ReadSerialPortAsync(string portName, int baudRate, int dataBits, StopBits stopBits, Parity parity, int readTimeout)
    {
        byte[] buffer = new byte[1024];

        await Task.Run(() =>
        {
            IntPtr hFile = CreateFile(portName, 0xc0000000, 0, IntPtr.Zero, 3, 0, IntPtr.Zero);
            if (hFile == (IntPtr)(-1))
            {
                throw new Exception("Failed to open serial port");
            }

            Dcb dcb = new Dcb();
            GetCommState(hFile, ref dcb);
            dcb.BaudRate = (uint)baudRate;
            dcb.ByteSize = (byte)dataBits;
            dcb.StopBits = (byte)stopBits;
            dcb.Parity = (byte)parity;
            SetCommState(hFile, ref dcb);

            CommTimeouts timeouts = new CommTimeouts();
            GetCommTimeouts(hFile, out timeouts);
            timeouts.ReadIntervalTimeout = 1000; // 1 second read interval timeout
            timeouts.ReadTotalTimeoutConstant = (uint)readTimeout;
            timeouts.ReadTotalTimeoutMultiplier = 0;
            SetCommTimeouts(hFile, ref timeouts);

            uint bytesRead = 0;
            if(!ReadFile(hFile, buffer, (uint)buffer.Length, out bytesRead, IntPtr.Zero))
            {
                throw new Exception("Failed to read serial port");
            }

            CloseHandle(hFile);
        });

        return buffer;
    }

    public static async Task WriteSerialPortAsync(string portName, int baudRate, int dataBits, StopBits stopBits, Parity parity, int writeTimeout, byte[] data)
    {
        await Task.Run(() =>
        {
            IntPtr hFile = CreateFile(portName, 0xc0000000, 0, IntPtr.Zero, 3, 0, IntPtr.Zero);
            if (hFile == (IntPtr)(-1))
            {
                throw new Exception("Failed to open serial port");
            }

            Dcb dcb = new Dcb();
            GetCommState(hFile, ref dcb);
            dcb.BaudRate = (uint)baudRate;
            dcb.ByteSize = (byte)dataBits;
            dcb.StopBits = (byte)stopBits;
            dcb.Parity = (byte)parity;
            SetCommState(hFile, ref dcb);

            CommTimeouts timeouts = new CommTimeouts();
            GetCommTimeouts(hFile, out timeouts);
            timeouts.WriteTotalTimeoutConstant = (uint)writeTimeout;
            timeouts.WriteTotalTimeoutMultiplier = 0;
