Let's refactor the code with these improvements in mind:

```rust
impl Record {
    pub fn new(line: &str) -> Result<Record, &'static str> {
        let fields: Vec<&str> = line.split('\t').collect();

        if fields.len() < MIN_BED_FIELDS {
            return Err("Bed line has less than 12 fields and cannot be parsed into a Record");
        }

        let chrom = fields[0];
        let tx_start = parse_u32_field(fields[1], "Cannot parse tx_start")?;
        let tx_end = parse_u32_field(fields[2], "Cannot parse tx_end")?;
        let id = Arc::new(fields[3].to_string());

        let exon_starts = fields[11].split(',')
            .filter(|s| !s.is_empty())
            .map(|x| x.parse::<u32>().map(|num| num + tx_start))
            .collect::<Result<Vec<_>, _>>()
            .map_err(|_| "Cannot parse exon_start")?;

        let exon_end_offsets = parse_offsets(fields[10])?;

        if exon_starts.len() != exon_end_offsets.len() {
            return Err("Exon start and end vectors have different lengths");
        }

        let exon_ends = exon_starts.iter()
            .zip(exon_end_offsets.iter())
            .map(|(&start, &offset)| start + offset)
            .collect::<Vec<_>>();

        let start_ends = exon_starts.into_iter()
            .zip(exon_ends.into_iter())
            .collect::<HashSet<(u32, u32)>>();

        Ok(Record {
            chrom: chrom.to_string(),
            info: (tx_start, tx_end, start_ends, id),
        })
    }
}

fn parse_u32_field(field: &str, error_message: &'static str) -> Result<u32, &'static str> {
    field.parse().map_err(move |_| error_message)
}

fn parse_offsets(field: &str) -> Result<Vec<u32>, &'static str> {
    field.split(',')
        .filter(|s| !s.is_empty())
        .map(|x| x.parse::<u32>())
        .collect::<Result<Vec<_>, _>>()
        .map_err(|_| "Cannot parse offsets")
}
```

In this refactored code:

- A helper function `parse_u32_field` is used to simplify the parsing of `u32` fields.
- A separate `parse_offsets` function is created to manage the comma-separated string split and parse for exon end offsets.
- Redundant `.to_string()` calls have been removed where not necessary.
- Direct parsing and arithmetic operations are performed within a single iterator chain, minimizing the collection and delaying the final collection as late as possible for efficiency.
- The `Arc::new` call is used to directly create an `Arc` from the string, which avoids an unnecessary intermediate `Arc::from` call.

