```csharp
using UnityEngine;

public class GrindableSurface : MonoBehaviour
{
    [Header("Surface Properties")]
    public Transform startPoint; // Assign in the inspector - the start of the rail
    public Transform endPoint; // Assign in the inspector - the end of the rail

    public Vector3 GetClosestPointOnSurface(Vector3 currentPosition)
    {
        // Calculate the closest point on the line segment between startPoint and endPoint
        Vector3 lineDir = endPoint.position - startPoint.position;
        float t = Vector3.Dot(currentPosition - startPoint.position, lineDir) / lineDir.sqrMagnitude;
        t = Mathf.Clamp01(t); // Clamp t between 0 and 1 to ensure it's on the segment
        return startPoint.position + t * lineDir; // Calculate the nearest position on the line segment
    }
}
```

