```java
import java.util.concurrent.locks.Lock;

public class LazySortedList {
    private final Node head;

    public LazySortedList() {
        this.head = new Node(Integer.MIN_VALUE);
        this.head.next = new Node(Integer.MAX_VALUE);
    }

    public boolean insert(int key) {
        while (true) {
            Node pred = this.head, curr = pred.next;
            while (curr.key < key) {
                pred = curr; curr = curr.next;
            }
            pred.lock.lock();
            curr.lock.lock();
            try {
                if (validate(pred, curr)) {
                    if (curr.key == key) { // already exists
                        return false;
                    } else {
                        Node node = new Node(key);
                        node.next = curr;
                        pred.next = node;
                        return true;
                    }
                }
            } finally {
                pred.lock.unlock();
                curr.lock.unlock();
            }
        }
    }

    public boolean contains(int key) {
        Node curr = this.head;
        while (curr.key < key)
            curr = curr.next;
        return curr.key == key && !curr.marked;
    }

    public boolean delete(int key) {
        while (true) {
            Node pred = this.head, curr = pred.next;
            while (curr.key < key) {
                pred = curr; curr = curr.next;
            }
            pred.lock.lock();
            curr.lock.lock();
            try {
                if (validate(pred, curr)) {
                    if (curr.key != key) {
                        return false;
                    } else {
                        curr.marked = true; // logical removal
                        pred.next = curr.next;
                        return true;
                    }
                }
            } finally {
                pred.lock.unlock();
                curr.lock.unlock();
            }
        }
    }

    private boolean validate(Node pred, Node curr) {
        return !pred.marked && !curr.marked && pred.next == curr;
    }
}
```

