public class LazySortedList {
    private final Node head;

    public LazySortedList() {
        this.head = new Node(Integer.MIN_VALUE); // Sentinel node at head
        this.head.next = new Node(Integer.MAX_VALUE); // Sentinel node at tail
    }

    public boolean insert(int key) {
        while (true) {
            Node pred = head, curr = head.next;
            while (curr.key < key) {
                pred = curr;
                curr = curr.next;
            }
            pred.lock();
            curr.lock();
            try {
                if (validate(pred, curr)) {
                    if (curr.key == key) { // Key already exists
                        return false;
                    } else {
                        Node newNode = new Node(key);
                        newNode.next = curr;
                        pred.next = newNode;
                        return true;
                    }
                }
            } finally {
                pred.unlock();
                curr.unlock();
            }
        }
    }

    public boolean delete(int key) {
        while (true) {
            Node pred = this.head;
            Node curr = pred.next;
            while (curr.key < key) {
                pred = curr;
                curr = curr.next;
            }
            pred.lock();
            curr.lock();
            try {
                if (validate(pred, curr)) {
                    if (curr.key == key) {
                        curr.marked = true; // Logically delete
                        pred.next = curr.next; // Physically unlink
                        return true;
                    } else {
                        return false; // Key not found
                    }
                }
            } finally {
                pred.unlock();
                curr.unlock();
            }
        }
    }

    public boolean contains(int key) {
        Node curr = this.head;
        while (curr.key < key)
            curr = curr.next;
        return curr.key == key && !curr.marked;
    }

    private boolean validate(Node pred, Node curr) {
        return !pred.marked && !curr.marked && pred.next == curr;
    }
