  final SEQ_LENGTH = seq;
  final SUB_LENGTH = sub;

  final s = List.generate(
      SEQ_LENGTH, (index) => index); // sequence of integers 0 to SEQ_LENGTH

  Map<List<int>, bool> uniqueSubs = {};

  for (var i = 0; i <= SEQ_LENGTH - SUB_LENGTH; i++) {
    final sub = s.sublist(i, i + SUB_LENGTH);

    if (!uniqueSubs.containsKey(sub)) {
      uniqueSubs[sub] = true;
      print(sub);
