      noStroke();
      ellipse((20 / 14) * scaleFactor, 0, scaleFactor / 1.5, scaleFactor / 2);

      // Draw legs
      strokeWeight(10);
      for (let i = -1; i <= 1; i += 2) {
        line(-scaleFactor / 3 * i, 0, -scaleFactor / 2 * i, -scaleFactor / 2 * i);
        line(-scaleFactor / 3 * i, 0, -scaleFactor / 2 * i, scaleFactor / 2 * i);
        line(scaleFactor / 3 * i, 0, scaleFactor / 2 * i, 0);
      }

      // Draw fractal tail
      strokeWeight(5);
      push();
      let curr_angle = frameCount / 100;
      for (let i = 0; i < tailSegments; i++) {

        translate((2 / 5) * scaleFactor / 2, 0);
        rotate(curr_angle);

        line(0, 0, scaleFactor / 2, 0);
        curr_angle *= -1;
      }
      pop();
    }
