using System.Runtime.InteropServices;

public class WindowFinder
{
    private const int MAX_TITLE_LENGTH = 256;

    [DllImport("user32.dll")]
    private static extern bool EnumWindows(EnumWindowsProc enumProc, IntPtr lParam);

    [DllImport("user32.dll")]
    private static extern int GetWindowText(IntPtr hWnd, char[] lpWindowText, int nMaxCount);

    [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    private static extern int GetClassName(IntPtr hWnd, char[] lpClassName, int nMaxCount);

    private delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);

    private static List<IntPtr> FindWindowsByCaptionAndClass(string caption, string className)
    {
        List<IntPtr> windows = new List<IntPtr>();

        EnumWindows(delegate(IntPtr hWnd, IntPtr lParam)
        {
            char[] buffer = new char[MAX_TITLE_LENGTH];
            GetWindowText(hWnd, buffer, MAX_TITLE_LENGTH);
            string windowTitle = new string(buffer);

            buffer = new char[MAX_TITLE_LENGTH];
            GetClassName(hWnd, buffer, MAX_TITLE_LENGTH);
            string windowClass = new string(buffer);

            if (windowTitle == caption && windowClass == className)
            {
                windows.Add(hWnd);
            }

            return true;
        }, IntPtr.Zero);

        return windows;
    }

