        string caption = "Window Caption";
        string className = "WindowClass";

        List<IntPtr> windows = FindWindowsByCaptionAndClass(caption, className);

        foreach (IntPtr window in windows)
        {
            Console.WriteLine("Window Handle: " + window);
        }

        Console.ReadLine();
    }
}
