	<h1>Simple HTML Game with Canvas</h1>

	<canvas id="gameCanvas" width="640" height="480"></canvas>

	<script>
		// Initialize the canvas and game variables
		const canvas = document.getElementById("gameCanvas");
		const ctx = canvas.getContext("2d");
		let ballX = canvas.width/2;
		let ballY = canvas.height/2;
		let ballRadius = 10;
		let ballSpeedX = 2;
		let ballSpeedY = -2;
		let paddleHeight = 10;
		let paddleWidth = 75;
		let paddleX = (canvas.width - paddleWidth) / 2;
		let rightPressed = false;
		let leftPressed = false;

		// Draw the ball on the canvas
		function drawBall() {
			ctx.beginPath();
			ctx.arc(ballX, ballY, ballRadius, 0, Math.PI * 2);
			ctx.fillStyle = "#0095DD";
			ctx.fill();
			ctx.closePath();
		}

		// Draw the paddle on the canvas
		function drawPaddle() {
			ctx.beginPath();
			ctx.rect(paddleX, canvas.height - paddleHeight, paddleWidth, paddleHeight);
			ctx.fillStyle = "#0095DD";
			ctx.fill();
			ctx.closePath();
		}

		// Move the ball and check for collisions with walls or the paddle
		function moveBall() {
			// Move the ball
			ballX += ballSpeedX;
			ballY += ballSpeedY;

			// Check for collisions with walls
			if (ballX + ballRadius >= canvas.width || ballX - ballRadius <= 0) {
				ballSpeedX = -ballSpeedX;
			}
			if (ballY - ballRadius <= 0) {
				ballSpeedY = -ballSpeedY;
			} else if (ballY + ballRadius >= canvas.height - paddleHeight) {
				// Check for collision with the paddle
				if (ballX >= paddleX && ballX <= paddleX + paddleWidth) {
					ballSpeedY = -ballSpeedY;
				} else {
					// Game over
					alert("GAME OVER");
					document.location.reload();
				}
			}
		}

		// Move the paddle based on keyboard input
		function movePaddle() {
			if (rightPressed && paddleX < canvas.width - paddleWidth) {
				paddleX += 7;
			} else if (leftPressed && paddleX > 0) {
				paddleX -= 7;
			}
		}

		// Draw the game on the canvas
		function draw() {
			ctx.clearRect(0, 0, canvas.width, canvas.height);

			drawBall();
			drawPaddle();

			moveBall();
			movePaddle();
		}

		// Handle keyboard input
		document.addEventListener("keydown", keyDownHandler, false);
		document.addEventListener("keyup", keyUpHandler, false);

		function keyDownHandler(event) {
			if (event.keyCode == 39) {
				rightPressed = true;
			} else if (event.keyCode == 37) {
				leftPressed = true;
			}
		}

		function keyUpHandler(event) {
			if (event.keyCode == 39) {
				rightPressed = false;
			} else if (event.keyCode == 37) {
				leftPressed = false;
			}
		}

		// Call the draw function every 10 milliseconds
		setInterval(draw, 10);
	</script>
</body>
</html>
```

