```
#include <iostream>
#include <cstdlib>
#include <ctime>

using namespace std;

// Constants
const int ROWS = 10;
const int COLS = 10;
const int BOMBS = 10;
const char COVERED = '*';
const char UNCOVERED = ' ';
const char BOMB = 'X';

/**
 * Cell struct for each cell in the game board
 */
struct Cell {
    bool bomb = false;  // Whether the cell contains a bomb
    bool uncovered = false; // Whether the cell has been uncovered yet
    int neighboringBombs = 0; // Number of neighboring cells that contain bombs
};

/**
 * GameBoard class for the game board
 */
class GameBoard {
public:
    GameBoard();

    // Methods
    void display();
    void uncover(int row, int col);
    bool isGameOver();
private:
    // Properties
    Cell board[ROWS][COLS];

    // Methods
    void placeBombs();
    void countNeighboringBombs();
};

/**
 * Constructor to initialize the game board
 */
GameBoard::GameBoard() {
    // Generate a new random seed
    srand(time(NULL));

    // Place the bombs on the board
    placeBombs();

    // Count the neighboring bombs for each cell
    countNeighboringBombs();
}

/**
 * Place the bombs on the board
 */
void GameBoard::placeBombs() {
    int bombsPlaced = 0;

    while (bombsPlaced < BOMBS) {
        int row = rand() % ROWS;
        int col = rand() % COLS;

        if (!board[row][col].bomb) {
            board[row][col].bomb = true;
            bombsPlaced++;
        }
    }
}

/**
 * Count the neighboring bombs for each cell
 */
void GameBoard::countNeighboringBombs() {
    for (int row = 0; row < ROWS; row++) {
        for (int col = 0; col < COLS; col++) {
            int neighborBombs = 0;

            // Check the neighboring cells for bombs
            for (int i = -1; i <= 1; i++) {
                for (int j = -1; j <= 1; j++) {
                    int neighborRow = row + i;
                    int neighborCol = col + j;

                    // Skip out-of-bounds cells
                    if (neighborRow < 0 || neighborRow >= ROWS ||
                        neighborCol < 0 || neighborCol >= COLS) {
                        continue;
                    }

                    if (board[neighborRow][neighborCol].bomb) {
                        neighborBombs++;
                    }
                }
            }

            board[row][col].neighboringBombs = neighborBombs;
        }
    }
}

/**
 * Display the game board
 */
void GameBoard::display() {
    cout << " ";
    for (int col = 0; col < COLS; col++) {
        cout << " " << col << " ";
    }
    cout << endl;

    for (int row = 0; row < ROWS; row++) {
        cout << row;
        for (int col = 0; col < COLS; col++) {
            Cell cell = board[row][col];

            if (!cell.uncovered) {
                cout << " " << COVERED << " ";
            } else if (cell.bomb) {
                cout << " " << BOMB << " ";
            } else if (cell.neighboringBombs > 0) {
                cout << " " << cell.neighboringBombs << " ";
            } else {
                cout << " " << UNCOVERED << " ";
            }
        }
        cout << endl;
    }
}

/**
 * Uncover a cell
 */
void GameBoard::uncover(int row, int col) {
    Cell& cell = board[row][col];

    if (!cell.uncovered && !cell.bomb) {
        cell.uncovered = true;

        if (cell.neighboringBombs == 0) {
            // Uncover neighboring cells if they have no neighboring bombs
            for (int i = -1; i <= 1; i++) {
                for (int j = -1; j <= 1; j++) {
                    int neighborRow = row + i;
                    int neighborCol = col + j;

                    // Skip out-of-bounds cells
                    if (neighborRow < 0 || neighborRow >= ROWS ||
                        neighborCol < 0 || neighborCol >= COLS) {
                        continue;
                    }

                    uncover(neighborRow, neighborCol);
                }
            }
        }
    }
}

/**
 * Check whether the game is over
 */
bool GameBoard::isGameOver() {
    bool gameOver = false;

    for (int row = 0; row < ROWS; row++) {
        for (int col = 0; col < COLS; col++) {
            Cell cell = board[row][col];

            if (cell.uncovered && cell.bomb) {
                gameOver = true;
            }

            if (!cell.uncovered && !cell.bomb) {
                gameOver = false;
                return gameOver;
            }
        }
    }

    return gameOver;
}

/**
 * Main function to run the game
 */
int main() {
    GameBoard gameBoard;

    while (!gameBoard.isGameOver()) {
        system("clear");

        cout << "Minesweeper" << endl;
        cout << endl;

        gameBoard.display();

        int row, col;
        cout << "Enter row: ";
        cin >> row;
        cout << "Enter col: ";
        cin >> col;

        gameBoard.uncover(row, col);
    }

    cout << "Game over!" << endl;
}
