Here's an example of an Arma function that dynamically generates units based on a unitType array and removes them if no players are within a specified distance:

```sqf
// Function to dynamically generate units
fnc_generateUnits = {
    params ["_unitTypes", "_quantity", "_distance"];

    private["_units"];

    // Initialize the units array
    _units = [];

    // Loop through each unitType
    {
        private["_count"];

        // Generate _quantity number of units for the current unitType
        for "_count" from 1 to _quantity do {
            // Generate a random position within a specified radius
            _position = player modelToWorld [(random 2 * _distance) - _distance, (random 2 * _distance) - _distance, 0];

            // Create a new unit of current unitType at the generated position
            _unit = createUnit [_x, _position, [], 0, "NONE"];

            // Add the created unit to the units array
            _units pushBack _unit;
        };
    } forEach _unitTypes;

    // Schedule a check to remove units if no players are within _distance
    [] spawn {
        params ["_units", "_distance"];

        waitUntil {
            // Get the number of players within _distance
            _playersNearby = count (allPlayers select {(_x distance2D player) <= _distance});

            // If no players are nearby, remove the units
            if (_playersNearby == 0) then {
                {
                    if (alive _x) then {
                        deleteVehicle _x;
                    };
                } forEach _units;

                // Exit the waitUntil loop
                true;
            };

            // Delay for some time before checking again
            sleep 10;
        };
    };
};

// Example usage
