car_widths = ones(1, num_cars) * car_width;
car_lengths = car_length(car_type);

% Define equilibrium velocity and desired minimum gap parameters for Krauss model
v_eq = max_speed;
d_min = 2;
delta = 4;
a_eq = b_max * (1 - (velocities ./ v_eq) .^ delta - (d_min * ones(1, num_cars) ./ (positions(2:end) - positions(1:end-1) - car_lengths(1:end-1) - car_lengths(2:end) - car_widths(1:end-1) - car_widths(2:end))));

% Define arrays to store position and velocity of each car in each time step
position_history = zeros(num_cars, ceil(road_length / max_speed / time_step));
velocity_history = zeros(num_cars, ceil(road_length / max_speed / time_step));

% Simulate traffic flow using Krauss model equations and record position and velocity data
for i = 1:size(position_history, 2)
    % Compute safe velocity and desired velocity for each car
    v_prev = [velocities(2:end) velocities(end)];
    v_safe = velocities - (positions(2:end) - positions(1:end-1) - car_lengths(1:end-1) - car_lengths(2:end) - car_widths(1:end-1) - car_widths(2:end)) ./ ((velocities + v_prev) ./ (2 * b_max) + tau_k);
    v_des = min(max_speed, velocities + a_max * delta_t, v_safe);

    % Compute acceleration for each car using Krauss model equations
    acceleration = a_eq .* (1 - (velocities ./ v_eq) .^ delta - (d_min * ones(1, num_cars) ./ (positions(2:end) - positions(1:end-1) - car_lengths(1:end-1) - car_lengths(2:end) - car_widths(1:end-1) - car_widths(2:end))));

    % Update velocity and position of each car using Krauss model equations
    velocities = max(0, velocities + acceleration .* delta_t - eta .* randn(1, num_cars));
    positions = positions + velocities .* delta_t;

    % Record position and velocity data for each car in this time step
    position_history(:, i) = positions';
    velocity_history(:, i) = velocities';
end

% Animate the simulation using plots and color-coding to represent different car types and lengths
