#include <Wire.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_ADDR 0x3C

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

void setup() {
  Wire.begin();   // Initialize I2C communication
  display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR);  // Initialize SSD1306 display

  display.clearDisplay();
  display.setTextColor(WHITE);
  display.setTextSize(2);
  display.setCursor(0, 0);
  display.println("I2C Data:");
  display.display();
}

void loop() {
  Wire.requestFrom(INPUT_DEVICE_ADDRESS, 1);  // Read 1 byte from the input I2C device

  if (Wire.available()) {
    uint8_t data = Wire.read();   // Read the received data

    display.clearDisplay();
    display.setCursor(0, 0);
    display.setTextSize(2);
    display.print("I2C Data: ");
    display.setTextSize(3);
    display.setCursor(0, 20);
    display.print(data);
    display.display();

    Wire.beginTransmission(OLED_ADDR);  // Begin I2C transmission to the SSD1306 display
    Wire.write(data);  // Send the same data to the display
    Wire.endTransmission();
  }

  delay(100);  // Adjust the delay as per your requirements
}
