    {
        if (!isGrinding)
        {
            isGrinding = true;
            startPosition = transform.position;
            startRotation = transform.rotation;

            // Position and direction are provided from the grindable object
            grindPosition = grindSurface;
            localGrindDirection = direction;

            // Optionally, set the player's position and rotation to match the grindable object
            transform.position = grindPosition.position;
            transform.rotation = localGrindDirection.rotation;

            // Start UI elements for grinding, like sliders
            grindBalanceSlider.gameObject.SetActive(true);
            grindBalanceSlider.value = 0; // Reset the grind balance slider
        }
    }

    public void EndGrinding()
    {
        if (isGrinding)
        {
            isGrinding = false;
            // Restore the player's position and rotation to avoid any snapping effects
            transform.position = startPosition;
            transform.rotation = startRotation;

            // Hide UI elements for grinding
            grindBalanceSlider.gameObject.SetActive(false);

            // Maybe add some logic here for when the player stops grinding, like slowing down
        }
    }

    private void GrindBalanceManager()
    {
        // Modify the slider value over time to simulate a balance mechanic
        grindBalanceSlider.value += grindDirection * Time.deltaTime * balanceDifficulty;

        // Change grind balance direction periodically to challenge the player
        balanceChangeTimer += Time.deltaTime;
        if (balanceChangeTimer >= balanceTimeDuration)
        {
            grindDirection *= -1; // Reverse direction
            balanceChangeTimer = 0f;
        }

        // Clamp slider value to prevent it from going out of bounds (usually -1 to 1)
        grindBalanceSlider.value = Mathf.Clamp(grindBalanceSlider.value, -1f, 1f);
    }

    private void GrindMovement()
    {
        // Perform the grinding movement here
        // You will need to configure this to match the behavior you want in your game
        Vector3 grindTargetPosition = grindPosition.position;
        transform.position = Vector3.MoveTowards(transform.position, grindTargetPosition, grindSpeed * Time.deltaTime);
