int main(int argc, char* argv[]) {
    printf("Slave begins execution\n");

    int child_number = atoi(argv[1]);
    const char* shmName = argv[2];
    const char* semName = argv[3];

    int shm_fd;
    struct CLASS *shm_ptr;

    // Open the shared memory segment
    shm_fd = shm_open(shmName, O_RDWR, 0666);
    if (shm_fd == -1) {
        printf("Slave: Shared memory failed: %s\n", strerror(errno));
        exit(1);
    }

    // Map shared memory segment in the address space of the process
    shm_ptr = (struct CLASS*)mmap(0, sizeof(struct CLASS), PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_ptr == MAP_FAILED) {
        printf("Slave: Map failed: %s\n", strerror(errno));
        exit(1);
    }

    // Access the shared memory structure and modify it
    sem_t* mutex_sem = sem_open(semName, 0);
    if (mutex_sem == SEM_FAILED) {
        printf("Slave: sem_open failed: %s\n", strerror(errno));
        exit(1);
    }

    // Acquire the semaphore
    if (sem_wait(mutex_sem) == -1) {
        printf("Slave: sem_wait failed: %s\n", strerror(errno));
        exit(1);
    }

    // Access and modify the shared memory structure
    int index = shm_ptr->index;
    shm_ptr->response[index] = child_number; // Write child number to response array
    shm_ptr->index++;

    // Release the semaphore
    if (sem_post(mutex_sem) == -1) {
        printf("Slave: sem_post failed: %s\n", strerror(errno));
        exit(1);
    }

    printf("Slave finished execution\n");

    return 0;
}
```

In this example, the slave process opens the shared memory segment, maps it to its address space, and acquires the semaphore for mutual exclusion (using the same semaphore name as the master process). It then accesses the shared memory structure, writes the child number to the response array, and increments the index. Finally, it releases the semaphore before exiting.

