              startTime + 0.15 * i * rhythmFactor,
              0.1 * noteDurationFactor
            );
          }
        }

        function loopChickadeeCall() {
          playChickadeeCall();
          setTimeout(loopChickadeeCall, Math.random() * 1000 + 500);
        }

        loopChickadeeCall();
      }

