function mu = wilkinson_shift(A)
    n = size(A, 1);
    B = A(n-1:n, n-1:n); 
    mu1 = (B(1,1) + B(2,2))/2 + ((B(2,2) - B(1,1))/2)^2 + B(1,2) * B(2,1);
    mu2 = (B(1,1) + B(2,2))/2 - ((B(2,2) - B(1,1))/2)^2 - B(1,2) * B(2,1);
    if abs(mu1 - A(n, n)) < abs(mu2 - A(n, n))
        mu = mu1;
    else
        mu = mu2;
    end
end
