```matlab
function [D, Q, iter] = aboda_final_p1(A, tol)
    n = size(A, 1);
    Q = eye(n);
    iter = 0;
    converged = false;

    while ~converged
        % Gram-Schmidt process to obtain Q_k and R_k
        Q_k = zeros(n);
        for i = 1:n
            v = A(:, i);
            for j = 1:i - 1
                v = v - dot(A(:, i), Q_k(:, j)) * Q_k(:, j);
            end
            Q_k(:, i) = v / norm(v);
        end

        R_k = Q_k' * A;

        % Update A and Q
        A = R_k * Q_k;
        Q = Q * Q_k;
        iter = iter + 1;

        T_k_0 = diag(A);
        T_k_minus_1 = abs(diag(A, -1));
        relative_error = max(T_k_minus_1(2:end) ./ abs(T_k_0(1:end-1)));
        converged = relative_error < tol;
    end

    D = diag(diag(A));
end
```

