        { name: 'Saturn', radius: 250, angle: 0, size: 8, color: 'khaki' },
        { name: 'Uranus', radius: 330, angle: 0, size: 5, color: 'lightblue' },
        { name: 'Neptune', radius: 380, angle: 0, size: 5, color: 'darkblue' },
