<script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    const planets = [
        { name: 'Mercury', orbitalPeriod: 88, radius: 58, angle: 0, color: 'gray' },
        { name: 'Venus', orbitalPeriod: 224.7, radius: 108, angle: 0, color: 'yellow' },
        { name: 'Earth', orbitalPeriod: 365.25, radius: 149, angle: 0, color: 'blue' },
        { name: 'Mars', orbitalPeriod: 687, radius: 227, angle: 0, color: 'red' },
        { name: 'Jupiter', orbitalPeriod: 4333, radius: 778, angle: 0, color: 'orange' },
        { name: 'Saturn', orbitalPeriod: 10759, radius: 1433, angle: 0, color: 'gold' },
        { name: 'Uranus', orbitalPeriod: 30799, radius: 2872, angle: 0, color: 'lightblue' },
        { name: 'Neptune', orbitalPeriod: 60190, radius: 4495, angle: 0, color: 'blue' },
        { name: 'Sun', orbitalPeriod: 0, radius: 0, angle: 0, color: 'yellow' }
    ];

    // Scale down for canvas visibility
    const scale = 0.2;
    const planetScale = 3; // Increase size of planet for visibility
    const center = { x: canvas.width / 2, y: canvas.height / 2 };

    // utility functions:
    function calculateAngle(orbitalPeriod) {
        // Calculate the angle based on the current time and orbital period
        const currentTime = new Date();
        return ((currentTime.getTime() / (orbitalPeriod * 1000)) % 1) * 2 * Math.PI;
    }

    function drawOrbit(radius) {
        ctx.beginPath();
        ctx.arc(center.x, center.y, radius * scale, 0, 2 * Math.PI);
        ctx.strokeStyle = "white";
        ctx.stroke();
    }

    function drawPlanet(planet) {
        const angle = calculateAngle(planet.orbitalPeriod);
        const x = center.x + Math.cos(angle) * planet.radius * scale;
        const y = center.y + Math.sin(angle) * planet.radius * scale;

        ctx.beginPath();
        ctx.arc(x, y, planetScale, 0, 2 * Math.PI);
        ctx.fillStyle = planet.color;
        ctx.fill();
        ctx.closePath();

        ctx.fillStyle = "white";
        ctx.font = "12px Arial";
        ctx.fillText(planet.name, x + 5, y + 5);
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw orbits
        for (let i = 0; i < planets.length - 1; i++) {
            drawOrbit(planets[i].radius);
        }

        // Draw the Sun at the center
        drawPlanet(planets[planets.length - 1]);

        // Draw planets
        for (let i = 0; i < planets.length - 1; i++) {
            drawPlanet(planets[i]);
        }

        requestAnimationFrame(draw); // Loop the simulation
    }

    draw(); // Start the simulation
</script>
