Now, here's a basic example in C++:

```cpp
#include <iostream>
#include <fstream>
#include <queue>
#include <set>
#include <filesystem>
#include <openssl/sha.h>
#include <nlohmann/json.hpp>

namespace fs = std::filesystem;
using json = nlohmann::json;

std::string hash_file(const fs::path& file_path) {
    unsigned char hash[SHA_DIGEST_LENGTH];
    char buf[1024];
    std::ifstream file(file_path.string(), std::ifstream::binary);

    if (!file) {
        std::cerr << "Cannot open file: " << file_path << std::endl;
        return "";
    }

    SHA_CTX sha1;
    SHA1_Init(&sha1);

    while (file.good()) {
        file.read(buf, sizeof(buf));
        SHA1_Update(&sha1, buf, file.gcount());
    }

    SHA1_Final(hash, &sha1);

    std::stringstream ss;
    for (auto& it : hash) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)it;
    }

    return ss.str();
}

void compare_directories(const fs::path& dir1, const fs::path& dir2, json& differ_json) {
    std::queue<std::pair<fs::path, fs::path>> dirs_queue;
    dirs_queue.push({dir1, dir2});

    while (!dirs_queue.empty()) {
        auto [current_dir1, current_dir2] = dirs_queue.front();
        dirs_queue.pop();

        std::set<std::string> entries1, entries2;
        for (const auto& entry : fs::directory_iterator(current_dir1)) {
            if (!fs::is_directory(entry))
                entries1.insert(entry.path().filename());
        }
        for (const auto& entry : fs::directory_iterator(current_dir2)) {
            if (!fs::is_directory(entry))
                entries2.insert(entry.path().filename());
        }

        for (const auto& entry : entries1) {
            if (entries2.find(entry) == entries2.end()) {
                differ_json["differences"].push_back({
                    {"file1", (current_dir1 / entry).string()}, 
                    {"file2", "missing"}
                });
            } else {
                auto file1_path = current_dir1 / entry;
                auto file2_path = current_dir2 / entry;
                auto hash1 = hash_file(file1_path);
                auto hash2 = hash_file(file2_path);
                if (hash1 != hash2) {
                    differ_json["differences"].push_back({
                        {"file1", file1_path.string()}, 
                        {"file2", file2_path.string()},
                        {"hash1", hash1},
                        {"hash2", hash2}
                    });
                }
            }
        }

        for (const auto& entry : entries2) {
            if (entries1.find(entry) == entries1.end()) {
                differ_json["differences"].push_back({
                    {"file1", "missing"}, 
                    {"file2", (current_dir2 / entry).string()}
                });
            }
        }

        for (const auto& entry : fs::directory_iterator(current_dir1)) {
            if (fs::is_directory(entry)) {
                auto other_entry = current_dir2 / entry.path().filename();
                if (fs::exists(other_entry)) {
                    dirs_queue.push({entry.path(), other_entry});
                }
            }
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <directory1> <directory2>" << std::endl;
        return 1;
    }

    fs::path dir1 = fs::path(argv[1]);
    fs::path dir2 = fs::path(argv[2]);

    if (!fs::exists(dir1) || !fs::is_directory(dir1) || !fs::exists(dir2) || !fs::is_directory(dir2)) {
        std::cerr << "Both arguments must be existing directories." << std::endl;
        return 1;
    }

    json differ_json;
    compare_directories(dir1, dir2, differ_json);

    auto timestamp = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    std::stringstream timestamp_ss;
    timestamp_ss << std::put_time(std::localtime(&timestamp), "%Y%m%d%H%M%S");
    std::string filename = "comparison_log_" + timestamp_ss.str() + ".json";
    std::ofstream log_file(filename);
