function processChatMessage(payload) {
    const { msg } = payload;

    // Regular expression that matches only letters, numbers, and the special characters !, @, #
    const validCharactersRegex = /^[a-zA-Z0-9!@#]+$/;

    // Check if the message contains only the allowed characters
    if (validCharactersRegex.test(msg)) {
        // If the message is valid, emit the chatUpdates event
