```
import java.util.*;

public class InventoryManagementSystem {
    private Map<String, List<Product>> productMap;

    public InventoryManagementSystem() {
        productMap = new HashMap<>();
    }

    public void addProduct(Product product) {
        String category = product.getCategory();
        List<Product> productList = getProductList(category);
        productList.add(product);
    }

    public void removeProduct(Product product) {
        String category = product.getCategory();
        List<Product> productList = getProductList(category);
        productList.remove(product);
    }

    public void updateProduct(Product oldProduct, Product newProduct) {
        String category = oldProduct.getCategory();
        List<Product> productList = getProductList(category);
        int index = productList.indexOf(oldProduct);
        productList.set(index, newProduct);
    }

    public List<Product> searchProductByName(String name) {
        List<Product> result = new ArrayList<>();
        for (List<Product> productList : productMap.values()) {
            for (Product product : productList) {
                if (product.getName().equals(name)) {
                    result.add(product);
                }
            }
        }
        return result;
    }

    public List<Product> searchProductByCategory(String category) {
        List<Product> productList = getProductList(category);
        return new ArrayList<>(productList);
    }

    public void generateReport() {
        for (Map.Entry<String, List<Product>> entry : productMap.entrySet()) {
            String category = entry.getKey();
            List<Product> productList = entry.getValue();
            System.out.println("Category: " + category);
            for (Product product : productList) {
                System.out.println("    " + product);
            }
        }
    }

    private List<Product> getProductList(String category) {
        List<Product> productList = productMap.get(category);
        if (productList == null) {
            productList = new ArrayList<>();
            productMap.put(category, productList);
        }
        return productList;
    }
}
```
This code defines an InventoryManagementSystem class that uses a HashMap to store products by category and a List to store different types of products. The class provides methods to add, remove, and update products, search for products by name or category, and generate reports. The Product class contains basic information about a product, such as its name, category, and price.

