以下是使用 WinAPI 获取驱动器信息的示例代码（C++）：

```cpp
#include <Windows.h>
#include <iostream>
#include <vector>

int main()
{
    // 获取当前系统中的所有逻辑驱动器
    DWORD drives = GetLogicalDrives();
    std::vector<char> driveNames;

    // 遍历所有逻辑驱动器
    for (char i = 'A', bit = 1; i <= 'Z'; ++i, bit <<= 1)
    {
        if (drives & bit)
        {
            // 添加驱动器名到 driveNames 中
            driveNames.push_back(i);
            std::cout << "Drive: " << i << std::endl;

            // 查询驱动器属性
            DWORD type = GetDriveType(std::string("\\\\.\\") + std::string(1, i) + ":");

            switch (type)
            {
            case DRIVE_UNKNOWN:
                std::cout << "Type: Unknown" << std::endl;
                break;
            case DRIVE_NO_ROOT_DIR:
                std::cout << "Type: No root directory" << std::endl;
                break;
            case DRIVE_REMOVABLE:
                std::cout << "Type: Removable disk" << std::endl;
                break;
            case DRIVE_FIXED:
                std::cout << "Type: Fixed disk" << std::endl;
                break;
            case DRIVE_REMOTE:
                std::cout << "Type: Network drive" << std::endl;
                break;
            case DRIVE_CDROM:
                std::cout << "Type: CD/DVD drive" << std::endl;
                break;
            case DRIVE_RAMDISK:
                std::cout << "Type: RAM disk" << std::endl;
                break;
            }

            TCHAR volumeName[MAX_PATH + 1] = { 0 };
            TCHAR fileSystem[MAX_PATH + 1] = { 0 };

            if (GetVolumeInformation(std::string(1, i) + ":\\", volumeName, MAX_PATH, nullptr, nullptr, nullptr, fileSystem, MAX_PATH))
            {
                std::cout << "Volume Name: " << volumeName << std::endl;
                std::cout << "File System: " << fileSystem << std::endl;
            }

            std::cout << std::endl;
        }
    }

    return 0;
}
```

运行此程序，将会打印出系统中每个逻辑驱动器的名称，类型，卷标和文件系统信息。`GetLogicalDrives` 函数用来获取系统中的所有逻辑驱动器的掩码值，而 `GetDriveType` 函数用来获取驱动器类型。`GetVolumeInformation` 函数可以获取驱动器的卷标和文件系统信息。

