Here is the code that sorts the contents of the given array in descending order using the Bubble Sort algorithm and displays the sorted array with 3 decimal places of precision:

```cpp
#include <iostream>
#include <iomanip>

void bubbleSort(double numbers[], int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (numbers[j] < numbers[j + 1]) {
                double temp = numbers[j];
                numbers[j] = numbers[j + 1];
                numbers[j + 1] = temp;
            }
        }
    }
}

int main() {
    double numbers[7] = {23.6, 46.7, 12.7, 35.1, 54.88, 78.7, 100.5};
    int size = sizeof(numbers) / sizeof(numbers[0]);

    bubbleSort(numbers, size);

    std::cout << std::fixed << std::setprecision(3);
    for (int i = 0; i < size; i++) {
        std::cout << numbers[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}
```

