void BLE_DeviceCallback(BLUETOOTH_DEVICE_INFO device_info, BLUETOOTH_DEVICE_INFO_UPDATE update_type, PVOID context);

int main() {
    BLUETOOTH_GATT_EVENT_HANDLE gatt_handle;
    BLUETOOTH_DEVICE_SEARCH_PARAMS search_params = { sizeof(search_params) };
    search_params.dwSize = sizeof(BLUETOOTH_DEVICE_SEARCH_PARAMS);
    search_params.fReturnUnrecognized = TRUE;
    search_params.fReturnUnknown = TRUE;
    search_params.fReturnAuthenticated = TRUE;
    search_params.fReturnRemembered = TRUE;

    HBLUETOOTH_DEVICE_FIND search_handle = BluetoothFindFirstDevice(&search_params, &device_info);
    if (search_handle == NULL) {
        printf("Failed to discover devices\n");
        return 1;
    }

    BLUETOOTH_DEVICE_INFO device_info = { sizeof(BLUETOOTH_DEVICE_INFO) };
    do {
        // Print device info
        wprintf(L"%s - %02X:%02X:%02X:%02X:%02X:%02X\n", device_info.szName,
                device_info.Address.rgBytes[0], device_info.Address.rgBytes[1],
                device_info.Address.rgBytes[2], device_info.Address.rgBytes[3],
                device_info.Address.rgBytes[4], device_info.Address.rgBytes[5]);

        // Register for BLE device events
        BLUETOOTH_GATT_EVENT_HANDLE gatt_handle = NULL;
        HRESULT result = BluetoothGATTRegisterEvent(&device_info.Address, BluetoothLEDeviceInterfaceId, BLE_DeviceCallback, NULL, &gatt_handle, BLUETOOTH_GATT_FLAG_NONE);
        if (result != S_OK) {
            printf("Failed to register for device events\n");
            continue;
        }

    } while (BluetoothFindNextDevice(search_handle, &device_info));

    BluetoothFindDeviceClose(search_handle);
    return 0;
}

