fn move_pos(record: &BedRecord, pos: u32, dist: i32) -> u32 {
    let mut pos = pos;
    assert!(record.tx_start <= pos && pos <= record.tx_end);

    // Find the initial exon using an iterator.
    let mut exon_index = record.exon_start.iter().zip(record.exon_end.iter())
        .position(|(start, end)| pos >= *start && pos <= *end)
        .expect("Position not in exons") as i16;

    let mut steps_remaining = dist.abs() as u32;
    let direction = if dist >= 0 { 1 } else { -1 };

    while steps_remaining > 0 {
        let (exon_start, exon_end) = (record.exon_start[exon_index as usize], record.exon_end[exon_index as usize]);
        // Determine if we can move within the exon.
        let steps_within_exon = if direction > 0 {
            exon_end - pos
        } else {
            pos - exon_start + 1 // +1 because pos can be equal to exon_start
        };

        let possible_steps = steps_within_exon.min(steps_remaining);
        steps_remaining -= possible_steps;
        pos = (pos as i32 + possible_steps as i32 * direction) as u32;

        if steps_remaining > 0 {
            exon_index += direction as i16;
            // Out of bounds exon index check
            if exon_index < 0 || exon_index >= record.exon_count as i16 {
